-- To do 0d0e9d8b: live-test af adminadgang kørt 14. okt. 2026, testkonti slettet (migrationen før denne).
update public.admin_todos
   set status = 'done', completed_at = coalesce(completed_at, now()), updated_at = now()
 where id = '0d0e9d8b-d979-48c5-bc4a-2b5bf9662810' and status <> 'done';
insert into public.admin_todo_comments (todo_id, body)
select '0d0e9d8b-d979-48c5-bc4a-2b5bf9662810',
 'Lukket 14. okt. 2026 (Claude, efter Jans ja): to almindelige testkonti (admintest-a/b@example.com, rolle user, ingen mail/push) oprettet og testet mod produktion, derefter slettet. 40 tjek bestået, 0 fejlet. Som almindelig bruger: (1) admin_audit_log, admin_todos, admin_todo_comments, client_errors, feedback_tickets og push_tokens giver 0 rækker; app_flags, api_usage og notification_events afvises (403); uden login afvises alt (401). Andres data i users, user_allergens, historik, favoritter, beskeder, familie, indkøbslister og indsendelser er usynlig (0 fremmede rækker), og direkte opslag på den anden kontos profil og allergier giver 0 rækker. (2) Edge-funktionen admin (users, stats, revision-log, enkeltbruger, PATCH, DELETE) svarer 403 til en almindelig konto og 401 uden login eller med kun anon-nøglen; delete-user på en andens konto afvises (400 "Kun admins kan slette andre brugere"), uden login 401. (3) Kontoen kan ikke ændre sin egen rolle ("Kun administratorer kan ændre rolle"), kan ikke oprette to do eller skrive i adminloggen (403), og forsøg på at ændre eller slette den anden kontos data rammer 0 rækker. Efter testen er alt uændret i databasen (begge konti stadig rolle user, ingen nye to do, adminloggen uberørt). Ikke testet: at en administrator ser rolleskift og ticketstatus i fanen Aktivitetslog (kræver login som admin; adminloggen er endnu tom, fordi der ikke har været admin-handlinger siden den kom). Forslag: Jan eller Bjørn skifter en tilfældig tickets status i admin og tjekker, at den dukker op i Aktivitetslog. Testkonti slettet og kontrolleret (0 rester).'
where exists (select 1 from public.admin_todos where id = '0d0e9d8b-d979-48c5-bc4a-2b5bf9662810');
